-- Bộ câu hỏi chuẩn của ERIS. Đây là script seed chạy thủ công, không phải migration.
-- Runtime chỉ đọc survey_questions; không tải hoặc đồng bộ câu hỏi từ file JavaScript.
-- Script chỉ thêm mã còn thiếu và dừng nếu nội dung cùng mã đã bị thay đổi.

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
SELECT pg_advisory_xact_lock(hashtext('ERIS_SURVEY_CATALOG'));

CREATE TEMP TABLE _survey_question_catalog_seed (
  category_name text NOT NULL,
  catalog_kind text NOT NULL,
  catalog_code text NOT NULL,
  question_text text NOT NULL,
  question_type text NOT NULL,
  answer_config jsonb NOT NULL,
  display_order integer NOT NULL,
  PRIMARY KEY (category_name, catalog_kind, catalog_code)
) ON COMMIT DROP;


DO $guard$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM _survey_question_catalog_seed seed
    LEFT JOIN survey_categories category ON category.name = seed.category_name
    WHERE category.id IS NULL
  ) THEN
    RAISE EXCEPTION 'Thiếu survey category cần thiết cho bộ câu hỏi chuẩn.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM survey_questions question
    WHERE question.survey_id IS NULL
      AND question.answer_config->'erisCatalog'->>'source' = 'ERIS_SURVEY_CATALOG'
    GROUP BY question.category_id,
             question.answer_config->'erisCatalog'->>'kind',
             question.answer_config->'erisCatalog'->>'code'
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Database có mã câu hỏi catalog bị trùng.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM _survey_question_catalog_seed seed
    JOIN survey_categories category ON category.name = seed.category_name
    JOIN survey_questions stored
      ON stored.survey_id IS NULL
     AND stored.category_id = category.id
     AND stored.answer_config->'erisCatalog'->>'source' = 'ERIS_SURVEY_CATALOG'
     AND stored.answer_config->'erisCatalog'->>'kind' = seed.catalog_kind
     AND stored.answer_config->'erisCatalog'->>'code' = seed.catalog_code
    WHERE stored.question_text IS DISTINCT FROM seed.question_text
       OR stored.question_type::text IS DISTINCT FROM seed.question_type
       OR stored.answer_config IS DISTINCT FROM seed.answer_config
       OR stored.display_order IS DISTINCT FROM seed.display_order
  ) THEN
    RAISE EXCEPTION 'Nội dung catalog trong database khác seed; script không tự ghi đè.';
  END IF;
END $guard$;

SELECT NULL,
       category.id,
       seed.question_text,
       seed.question_type::survey_question_type,
       seed.answer_config,
       seed.display_order
FROM _survey_question_catalog_seed seed
JOIN survey_categories category ON category.name = seed.category_name
WHERE NOT EXISTS (
  SELECT 1
  FROM survey_questions stored
  WHERE stored.survey_id IS NULL
    AND stored.category_id = category.id
    AND stored.answer_config->'erisCatalog'->>'source' = 'ERIS_SURVEY_CATALOG'
    AND stored.answer_config->'erisCatalog'->>'kind' = seed.catalog_kind
    AND stored.answer_config->'erisCatalog'->>'code' = seed.catalog_code
)
ORDER BY category.id, seed.catalog_kind, seed.display_order;

SELECT category.name,
       count(*) FILTER (
         WHERE question.answer_config->'erisCatalog'->>'kind' = 'SATISFACTION'
       ) AS satisfaction_questions,
       count(*) FILTER (
         WHERE question.answer_config->'erisCatalog'->>'kind' = 'BANK'
       ) AS bank_questions
FROM survey_categories category
LEFT JOIN survey_questions question
  ON question.category_id = category.id
 AND question.survey_id IS NULL
 AND question.answer_config->'erisCatalog'->>'source' = 'ERIS_SURVEY_CATALOG'
GROUP BY category.id, category.name
ORDER BY category.id;

COMMIT;
